function projectBrowser(){return `<div class="eyebrow">VOTRE ESPACE</div><div class="intro"><div><h1>Vos projets.</h1><p>Retrouvez vos favoris et reprenez le dernier contexte ouvert.</p></div><button class="primary" data-add-project>Importer depuis GitHub</button></div><div class="project-browser-filters"><input id="project-query" aria-label="Rechercher un projet" placeholder="Rechercher un projet ou un repo…" value="${escape(projectQuery)}"><div class="segmented">${[['all','Tous'],['favorites','Favoris'],['recent','Récents']].map(([k,l])=>`<button data-project-mode="${k}" class="${projectMode===k?'active':''}">${l}</button>`).join('')}</div></div><div id="project-cards" class="project-grid">${projectCards()}</div>`;}
function projectCards(){let projects=sortedProjects(state.projects).filter(p=>(p.name+' '+p.repo).toLowerCase().includes(projectQuery.toLowerCase()));if(projectMode==='favorites')projects=projects.filter(p=>p.favorite);if(projectMode==='recent')projects=projects.filter(p=>p.last_opened).sort((a,b)=>b.last_opened.localeCompare(a.last_opened));return projects.map(p=>`<div class="project-tile"><button class="project-card" data-project="${escape(p.id)}"><span class="project-icon">${escape(p.name[0].toUpperCase())}</span><div><h3>${escape(p.name)}</h3><p>${escape(p.repo)}</p><small>${state.workspaces.filter(w=>w.project_id===p.id).length} espace(s)${p.last_opened?' · '+escape(new Date(p.last_opened).toLocaleDateString('fr-FR')):''}</small></div></button><button class="favorite-button ${p.favorite?'active':''}" data-favorite="${escape(p.id)}" aria-label="${p.favorite?'Retirer des favoris':'Ajouter aux favoris'} : ${escape(p.name)}" aria-pressed="${!!p.favorite}">${p.favorite?'★':'☆'}</button></div>`).join('')||'<div class="welcome"><h2>Aucun projet ici.</h2><p>Essayez un autre filtre ou importez un repo GitHub.</p><button class="primary" data-add-project>Importer un repo</button></div>';}
function bindProjectBrowser(){const paint=()=>{$('#project-cards').innerHTML=projectCards();bindContent();bindFavorites();};$('#project-query')?.addEventListener('input',e=>{projectQuery=e.target.value;paint();});document.querySelectorAll('[data-project-mode]').forEach(b=>b.onclick=()=>{projectMode=b.dataset.projectMode;document.querySelectorAll('[data-project-mode]').forEach(x=>x.classList.toggle('active',x===b));paint();});bindFavorites();}
function bindFavorites(){document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=async()=>{const p=state.projects.find(p=>p.id===b.dataset.favorite);b.disabled=true;try{await api(`projects/${p.id}/favorite`,'POST',{favorite:!p.favorite});await refresh();}catch(e){toast(e.message);b.disabled=false;}});}
async function addProject(){
  modal('Importer depuis GitHub',`<p>Choisissez un repo. Son contexte et ses tâches resteront regroupés dans Lew.</p><div class="repo-toolbar"><label class="field">Compte public<input id="repo-owner" value="" placeholder="Compte configuré sur le serveur" autocomplete="off"></label><button class="secondary" id="reload-repos">Charger</button></div><input id="repo-query" class="repo-query" placeholder="Rechercher parmi les repos chargés…" aria-label="Rechercher un repo"><p id="repo-source" class="muted">Chargement de GitHub…</p><div id="repo-list" class="repo-list"></div><div class="form-actions"><button class="secondary" id="manual-project">Ajouter manuellement</button><button class="secondary" id="more-repos" hidden>Charger la suite</button></div>`);
  let repos=[],nextPage=1,busy=false,generation=0;
  const draw=()=>{if(!$('#repo-list'))return;const q=$('#repo-query').value.toLowerCase();const imported=new Map(state.projects.map(p=>[p.repo.toLowerCase(),p.id]));const found=repos.filter(r=>(r.repo+' '+r.description).toLowerCase().includes(q));$('#repo-list').innerHTML=found.map(r=>`<button class="repo-option" data-import-repo="${escape(r.repo)}" ${r.archived?'disabled':''}><span><strong>${escape(r.repo)}</strong><small>${escape(r.description||r.defaultBranch)} · ${r.private?'privé':'public'}${r.archived?' · archivé':''}</small></span><span>${imported.has(r.repo.toLowerCase())?'Ouvrir':'Importer →'}</span></button>`).join('')||'<p class="muted">Aucun repo correspondant parmi ceux chargés.</p>';document.querySelectorAll('[data-import-repo]').forEach(b=>b.onclick=async()=>{const existing=imported.get(b.dataset.importRepo.toLowerCase());if(existing){closeModal();navigate('project',existing);return;}b.disabled=true;try{const r=await api('github/import','POST',{repo:b.dataset.importRepo});closeModal();await refresh();navigate('project',r.id);toast('Repo importé');}catch(e){toast(e.message);b.disabled=false;}});};
  const load=async(reset=false)=>{if(busy)return;busy=true;const run=++generation;$('#reload-repos').disabled=true;$('#more-repos').disabled=true;try{if(reset){repos=[];nextPage=1;}const data=await api(`github/repos?page=${nextPage}&owner=${encodeURIComponent($('#repo-owner').value.trim())}`);if(run!==generation||$('#modal-title').textContent!=='Importer depuis GitHub')return;repos=[...new Map([...repos,...data.repos].map(r=>[r.repo,r])).values()];nextPage=data.nextPage;$('#repo-source').textContent=data.authenticated?`${repos.length} repos accessibles avec votre token GitHub.`:`${repos.length} repos publics de ${data.owner}. Pour les repos privés, configurez GITHUB_TOKEN dans .env.`;if(!data.authenticated)$('#repo-owner').value=data.owner;$('.repo-toolbar').hidden=data.authenticated;$('#more-repos').hidden=!nextPage;draw();}catch(e){if($('#repo-source'))$('#repo-source').textContent=e.message;}finally{busy=false;if($('#reload-repos'))$('#reload-repos').disabled=false;if($('#more-repos'))$('#more-repos').disabled=false;}};
  $('#repo-query').oninput=draw;$('#reload-repos').onclick=()=>load(true);$('#more-repos').onclick=()=>load();$('#manual-project').onclick=addManualProject;await load();
}
function contextBar(p,w){if(!p)return '';const spaces=state.workspaces.filter(x=>x.project_id===p.id);return `<div class="context-bar"><label>Projet<select id="context-project" aria-label="Projet actif">${sortedProjects(state.projects).map(x=>`<option value="${escape(x.id)}" ${x.id===p.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select></label><label>Branche · espace<select id="context-workspace" aria-label="Branche et espace de travail"><option value="">Vue du projet</option>${spaces.map(x=>`<option value="${escape(x.id)}" ${x.id===w?.id?'selected':''}>${escape(x.branch)} · ${escape(x.title)}</option>`).join('')}<option value="new">+ Nouvelle tâche depuis une branche</option></select></label>${w?`<div class="context-identity"><span title="${escape(w.cwd)}">Worktree <code>${escape(w.cwd)}</code></span><span>Conversation <code>${escape(w.thread_id||'au premier échange')}</code></span></div>`:''}</div>`;}
function bindContextBar(){$('#context-project')?.addEventListener('change',e=>navigate('project',e.target.value));$('#context-workspace')?.addEventListener('change',e=>{if(e.target.value==='new'){e.target.value=workspaceId||'';addWorkspace();}else if(e.target.value){const w=state.workspaces.find(w=>w.id===e.target.value);navigate('workspace',w.project_id,w.id);}else navigate('project',projectId);});}
function contextPicker(){modal('Changer de contexte',`<input class="repo-query" id="context-query" aria-label="Rechercher un contexte" placeholder="Projet, branche ou conversation…" autofocus><div id="context-results" class="repo-list"></div>`);const draw=()=>{const q=$('#context-query').value.toLowerCase();$('#context-results').innerHTML=sortedProjects(state.projects).map(p=>{const spaces=state.workspaces.filter(w=>w.project_id===p.id&&(p.name+' '+w.title+' '+w.branch+' '+(w.thread_id||'')).toLowerCase().includes(q));return `${(p.name+' '+p.repo).toLowerCase().includes(q)?`<button class="context-option" data-context-project="${escape(p.id)}"><strong>${p.favorite?'★ ':''}${escape(p.name)}</strong><small>${escape(p.repo)} · Vue du projet</small></button>`:''}${spaces.map(w=>`<button class="context-option ${w.id===workspaceId?'current':''}" data-context-workspace="${escape(w.id)}"><strong>${escape(p.name)} / ${escape(w.title)}</strong><small>${escape(w.branch)} · ${escape(labels[w.status])}</small><code>${escape(w.cwd)}</code><small>Conversation : ${escape(w.thread_id||'nouvelle')}</small></button>`).join('')}`;}).join('')||'<p class="muted">Aucun contexte correspondant. Importez un repo ou créez une tâche depuis un projet.</p>';document.querySelectorAll('[data-context-project]').forEach(b=>b.onclick=()=>{closeModal();navigate('project',b.dataset.contextProject);});document.querySelectorAll('[data-context-workspace]').forEach(b=>b.onclick=()=>{const w=state.workspaces.find(w=>w.id===b.dataset.contextWorkspace);closeModal();navigate('workspace',w.project_id,w.id);});};$('#context-query').oninput=draw;draw();$('#context-query').focus();}

function patchHTML(patch){return `<div class="diff-table">${diffLines(patch).map(l=>`<div class="diff-line ${l.kind}"><span class="line-number">${l.old??''}</span><span class="line-number">${l.next??''}</span><code>${escape(l.text)}</code></div>`).join('')}</div>`;}
const toolLabels={commandExecution:'Commande',fileChange:'Fichiers modifiés',mcpToolCall:'Outil MCP',webSearch:'Recherche web',plan:'Plan',dynamicToolCall:'Outil'};
const itemStatus=s=>({inProgress:'En cours',completed:'Terminé',failed:'Échec',declined:'Refusé',pending:'En attente'}[s]||s||'');
function messageHTML(m){
  if(m.type==='approval')return `<section class="approval" data-message-id="${escape(m.id)}"><strong>${m.resolved?'Validation traitée':'Votre accord est requis'}</strong>${m.network?`<p>Accès réseau : <code>${escape(m.network.protocol)}://${escape(m.network.host)}</code></p>`:''}${m.command?`<pre>${escape(m.command)}</pre>`:''}${m.reason?`<p>${escape(m.reason)}</p>`:''}${m.cwd?`<small>Dossier : ${escape(m.cwd)}</small>`:''}${m.grantRoot?`<p>Accès aux fichiers : ${escape(m.grantRoot)}</p>`:''}${(m.changes||[]).map(c=>`<details><summary>${escape(c.path)}</summary>${patchHTML(c.diff)}</details>`).join('')}${m.resolved?`<p class="muted">${m.accepted===true?'Autorisée':m.accepted===false?'Refusée':'Cette demande n’est plus active.'}</p>`:`<div class="approval-actions"><button class="primary" data-approve="${escape(m.requestId)}">Autoriser cette action</button><button class="secondary" data-decline="${escape(m.requestId)}">Refuser</button></div>`}</section>`;
  if(m.type==='fileChange')return `<details class="tool-card" data-message-id="${escape(m.id)}"><summary><strong>Fichiers modifiés · ${(m.changes||[]).length}</strong><span class="badge">${escape(itemStatus(m.status))}</span></summary>${(m.changes||[]).map(c=>`<details class="changed-file"><summary>${escape(c.path)} <small>${escape(typeof c.kind==='object'?c.kind.type:c.kind)}</small></summary>${c.diff?patchHTML(c.diff):'<p class="muted">Diff indisponible.</p>'}</details>`).join('')}</details>`;
  if(toolLabels[m.type]&&m.type!=='plan'){const output=m.output||m.result||m.contentItems;const text=typeof output==='string'?output:output?JSON.stringify(output,null,2):'';return `<details class="tool-card" data-message-id="${escape(m.id)}"><summary><strong>${escape(toolLabels[m.type])}${m.server?' · '+escape(m.server):''}</strong><span class="badge ${m.status==='failed'?'failed':''}">${escape(itemStatus(m.status))}</span></summary><pre>${escape(m.command||m.tool||m.query||'')}</pre>${m.cwd?`<small>${escape(m.cwd)}</small>`:''}${text?`<pre class="tool-output">${escape(text.slice(0,30000))}${text.length>30000?'\n… sortie tronquée':''}</pre>`:''}${m.exitCode!==undefined&&m.exitCode!==null?`<small>Code de sortie : ${escape(m.exitCode)}</small>`:''}</details>`;}
  if(!['agentMessage','user','system','error','delivery','plan'].includes(m.type))return '';
  return `<div class="message ${m.type==='agentMessage'?'agent':m.type}" data-message-id="${escape(m.id)}"><span class="author">${m.type==='user'?'VOUS':m.type==='agentMessage'?'CODEX':m.type==='error'?'À VÉRIFIER':'LEW'}</span>${escape(m.text)}${m.url?`<p><a href="${escape(safeURL(m.url))}" target="_blank" rel="noopener noreferrer">Voir sur GitHub ↗</a></p>`:''}</div>`;
}
function paintConversation(id,data){if(view!=='workspace'||workspaceId!==id||!$('#messages'))return;const signature=JSON.stringify(data);if(signature===eventSignature&&$('#messages').dataset.painted)return;eventSignature=signature;
  const node=$('#messages'),scroll=node.scrollTop,follow=!node.dataset.painted||node.scrollHeight-node.clientHeight-scroll<90;const expanded=new Set([...node.querySelectorAll('details[open][data-message-id]')].map(n=>n.dataset.messageId));
  const model=conversation(data.events,{pendingIds:data.pendingIds});node.innerHTML=model.messages.map(messageHTML).join('')||'<p class="muted">Votre espace est prêt. Donnez une première instruction à Codex.</p>';node.dataset.painted='true';node.querySelectorAll('details[data-message-id]').forEach(n=>{n.open=expanded.has(n.dataset.messageId);});
  $('#agent-plan').innerHTML=model.plan.length?`<details class="agent-plan" open><summary>Plan de la tâche</summary>${model.plan.map(s=>`<div><span class="${s.status==='completed'?'good':'muted'}">${s.status==='completed'?'✓':s.status==='inProgress'?'◷':'○'}</span>${escape(s.step)}<small>${escape(itemStatus(s.status))}</small></div>`).join('')}</details>`:'';
  document.querySelectorAll('[data-approve],[data-decline]').forEach(b=>b.onclick=async()=>{const key=b.dataset.approve??b.dataset.decline;const request=model.messages.find(m=>m.type==='approval'&&String(m.requestId)===key);b.disabled=true;try{await api(`workspaces/${id}/approval`,'POST',{id:request.requestId,accept:b.hasAttribute('data-approve')});streamHealthy=false;await loadWorkspace();}catch(e){toast(e.message);b.disabled=false;}});
  if(follow)node.scrollTop=node.scrollHeight;else node.scrollTop=scroll;
}
function stopStream(){streamController?.abort();streamController=null;streamWorkspace=null;streamHealthy=false;clearTimeout(streamRetry);}
function ensureStream(id){if(streamWorkspace===id&&streamController)return;stopStream();streamWorkspace=id;const controller=new AbortController();streamController=controller;
  const run=async()=>{try{const cache=eventCache.get(id)||{events:[],pendingIds:[]},cursor=cache.events.at(-1)?.id||'0';const response=await fetch(`/api/workspaces/${encodeURIComponent(id)}/stream?after=${encodeURIComponent(cursor)}`,{headers:accessToken?{Authorization:'Bearer '+accessToken}:{},signal:controller.signal});if(!response.ok||!response.headers.get('content-type')?.includes('text/event-stream'))throw new Error('Flux indisponible');streamHealthy=true;const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const line=frame.split('\n').find(l=>l.startsWith('data: '));if(!line)continue;const data=JSON.parse(line.slice(6));if(data.error)throw new Error(data.error);if(controller.signal.aborted||workspaceId!==id||view!=='workspace')return;const current=eventCache.get(id)||{events:[]};const events=[...new Map([...current.events,...data.events].map(e=>[String(e.id),e])).values()];const next={events,pendingIds:data.pendingIds};eventCache.set(id,next);paintConversation(id,next);}}}catch(e){if(!controller.signal.aborted)streamHealthy=false;}finally{if(!controller.signal.aborted&&workspaceId===id&&view==='workspace'){streamHealthy=false;streamController=null;streamRetry=setTimeout(()=>ensureStream(id),2500);}}};void run();}
function safeURL(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function checksHTML(checks){const label={none:'Aucun contrôle publié',pending:'Contrôles en cours',success:'Contrôles réussis',failure:'Des contrôles ont échoué',unknown:'État incomplet'};return `<section class="review-panel"><h3>Checks CI <span class="badge ${checks.state==='failure'?'failed':checks.state==='success'?'completed':''}">${escape(label[checks.state])}</span></h3>${checks.incomplete?'<p class="muted">Certains contrôles sont absents ou inaccessibles avec ce token.</p>':''}${checks.items.map(c=>`<a class="check-row" href="${escape(safeURL(c.url))}" target="_blank" rel="noopener noreferrer"><span>${escape(c.name)}</span><span>${escape(c.state)}</span></a>`).join('')}</section>`;}
function openPR(number,p=projectId){selectedPR=number;prData=null;prTab='overview';navigate('pr',p);}
async function loadPR(){const p=projectId,number=selectedPR,run=++prRequest;if(!p||!number){navigate('projects');return;}const node=$('#pr-review');if(!node)return;
  try{if(!prData||prData.project!==p||prData.pr.number!==number){const data=await api(`projects/${p}/prs/${number}`);if(run!==prRequest||view!=='pr'||projectId!==p||selectedPR!==number)return;prData={...data,project:p};}paintPR();}catch(e){if(run===prRequest&&view==='pr'&&$('#pr-review')){$('#pr-review').innerHTML=`<div class="alert">${escape(e.message)} <button id="retry-pr">Réessayer</button></div>`;$('#retry-pr').onclick=loadPR;}}
}
function paintPR(){if(view!=='pr'||!$('#pr-review')||!prData)return;const d=prData,p=d.pr,w=state.workspaces.find(w=>w.project_id===projectId&&w.branch===p.head);
  $('#pr-review').innerHTML=`<div class="intro pr-intro"><div><div class="eyebrow">PULL REQUEST #${p.number} · ${escape(p.author)}</div><h1>${escape(p.title)}</h1><p><span class="badge ${p.state==='merged'?'completed':''}">${escape(p.state==='merged'?'Mergée':p.state==='closed'?'Fermée':p.draft?'Brouillon':'Ouverte')}</span> <code>${escape(p.head)}</code> → <code>${escape(p.base)}</code></p></div><div class="project-actions"><button class="secondary" id="refresh-pr">Actualiser</button><a class="secondary" href="${escape(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">GitHub ↗</a>${w?'<button class="primary" id="resume-pr-workspace">Reprendre la conversation</button>':''}</div></div><div class="review-tabs">${[['overview','Vue d’ensemble'],['files',`Fichiers (${p.changedFiles})`],['comments',`Commentaires & revues (${d.comments.length})`]].map(([k,l])=>`<button data-pr-tab="${k}" class="${prTab===k?'active':''}">${escape(l)}</button>`).join('')}</div>${d.warnings.length?`<div class="alert">Chargement partiel : ${d.warnings.map(x=>escape(x.section+' · '+x.message)).join('<br>')}</div>`:''}<div class="pr-tab-content">${prTab==='overview'?`<div class="review-overview"><section class="review-panel"><h3>Description</h3><p class="pr-body">${escape(p.body||'Aucune description.')}</p><div class="diff-stat"><span class="good">+${p.additions}</span><span class="danger">−${p.deletions}</span><span>${p.changedFiles} fichier(s)</span></div><p class="muted">${p.mergeable===false?'Conflits détectés avec la branche cible.':p.mergeable===true?'GitHub ne signale pas de conflit de fusion.':'GitHub n’a pas encore calculé la possibilité de fusion.'}</p></section>${checksHTML(d.checks)}</div>`:prTab==='files'?`${d.truncated.files?'<div class="alert">Liste limitée aux 3 000 premiers fichiers. Consultez GitHub pour la suite.</div>':''}<div class="pr-files">${d.files.map((f,i)=>`<details class="pr-file" ${i===0?'open':''}><summary><code>${escape(f.path)}</code><span class="muted">${escape(f.status)}</span><span class="good">+${f.additions}</span><span class="danger">−${f.deletions}</span></summary>${f.previousPath?`<p class="muted">Ancien chemin : ${escape(f.previousPath)}</p>`:''}${f.patch?patchHTML(f.patch):'<p class="muted">Diff indisponible dans l’API (fichier binaire ou diff trop volumineux). Consultez GitHub.</p>'}</details>`).join('')||'<p class="muted">Aucun fichier chargé.</p>'}</div>`:`${Object.entries(d.truncated).some(([k,v])=>k!=='files'&&v)?'<div class="alert">Certaines discussions dépassent la limite de chargement. Consultez GitHub pour la suite.</div>':''}<div class="pr-comments">${d.comments.map(c=>`<article class="review-panel"><div class="comment-meta"><strong>${escape(c.author)}</strong><span class="badge">${escape(c.type==='inline'?'Sur le code':c.type==='review'?c.state:'Discussion')}</span><time>${escape(c.createdAt?new Date(c.createdAt).toLocaleString('fr-FR'):'')}</time><a href="${escape(safeURL(c.url))}" target="_blank" rel="noopener noreferrer">↗</a></div>${c.path?`<p class="muted"><code>${escape(c.path)}${c.line?':'+c.line:''}</code></p>`:''}<p class="pr-body">${escape(c.body||'Revue sans commentaire.')}</p></article>`).join('')||'<p class="muted">Aucun commentaire ni revue pour le moment.</p>'}</div>`}</div>`;
  $('#refresh-pr').onclick=()=>{prData=null;loadPR();};$('#resume-pr-workspace')?.addEventListener('click',()=>navigate('workspace',w.project_id,w.id));document.querySelectorAll('[data-pr-tab]').forEach(b=>b.onclick=()=>{prTab=b.dataset.prTab;paintPR();});
}
$('#context-switch').onclick=contextPicker;
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='j'){e.preventDefault();contextPicker();}});
